"""KMP (Knuth-Morris-Pratt) string matching algorithm."""


def build_lps(pattern: str) -> list[int]:
    """Build the Longest Proper Prefix which is also Suffix table.

    lps[i] = length of the longest proper prefix of pattern[0..i]
    that is also a suffix of pattern[0..i].
    """
    m = len(pattern)
    lps = [0] * m
    length = 0  # length of the previous longest prefix-suffix
    i = 1

    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]  # fall back without incrementing i
            else:
                lps[i] = 0
                i += 1

    return lps


def kmp_search(text: str, pattern: str) -> list[int]:
    """Return all starting indices where pattern occurs in text."""
    n, m = len(text), len(pattern)
    if m == 0:
        return list(range(n + 1))

    lps = build_lps(pattern)
    result = []
    i = 0  # index for text
    j = 0  # index for pattern

    while i < n:
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == m:
            result.append(i - j)
            j = lps[j - 1]
        elif i < n and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result


if __name__ == "__main__":
    # Basic examples
    tests = [
        ("ABABDABACDABABCABAB", "ABABCABAB"),
        ("AAAAAA", "AA"),
        ("ABCABCABC", "ABC"),
        ("hello world", "world"),
        ("abcdef", "xyz"),
    ]

    for text, pattern in tests:
        positions = kmp_search(text, pattern)
        print(f'text="{text}"  pattern="{pattern}"  -> {positions}')
